import { mkdir, readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';

export async function bundlePlaytest(){
const root=process.cwd();
const entryOrder=[
  'src/presentation/miracle-choice.js','src/presentation/target-choice.js','src/presentation/our-victory-choice.js','src/presentation/ark-choice.js','src/presentation/reaction-choice.js','src/presentation/qa-hand-normalizer.js','src/presentation/empty-tomb-reaction.js','src/presentation/ashes-stronghold.js','src/presentation/overcome-death-reaction.js','src/presentation/hope-insight.js','src/presentation/effect-zone.js','src/presentation/dawn-knock.js','src/presentation/rebuild-choice.js','src/presentation/browser-watchdog.js','src/presentation/final-results.js','src/presentation/app.js','src/presentation/tag-card-face-qa.js','src/presentation/stronghold-card-template.js','src/presentation/qa-inspector.js','src/presentation/tabletop-history.js','src/presentation/round-resolution.js','src/presentation/resource-deck.js','src/presentation/foil-prototype.js','src/presentation/lies-choice.js','src/presentation/audio-system.js','src/presentation/hand-stability.js','src/presentation/battle-log.js','src/presentation/reaction-five-qa.js','src/presentation/false-tongue-choice.js','src/presentation/desire-seed-choice.js','src/presentation/mission-reward-choice.js','src/presentation/aftermath-choice.js','src/presentation/narrow-choice.js','src/presentation/cup-choice.js','src/presentation/overflow-choice.js','src/presentation/rope-choice.js','src/presentation/choice-batch-qa.js'
];
const modules=new Map(), imports=new Map(), exported=new Map();
const normalize=file=>path.posix.normalize(file.replaceAll('\\','/'));
const resolve=(from,spec)=>normalize(path.relative(root,path.resolve(path.dirname(path.resolve(root,from)),spec)));
async function visit(file){file=normalize(file);if(modules.has(file))return;const source=await readFile(path.resolve(root,file),'utf8');modules.set(file,source);const list=[];const re=/import\s*\{([^}]+)\}\s*from\s*['"]([^'"]+)['"];?/g;for(const match of source.matchAll(re)){const target=resolve(file,match[2]);const names=match[1].split(',').map(v=>v.trim()).filter(Boolean).map(v=>{const [name,alias]=v.split(/\s+as\s+/);return{name:name.trim(),alias:(alias??name).trim()};});list.push({full:match[0],target,names});if(!exported.has(target))exported.set(target,new Set());for(const item of names)exported.get(target).add(item.name);await visit(target);}imports.set(file,list);}
for(const entry of entryOrder)await visit(entry);
function compile(file){let source=modules.get(file),list=imports.get(file)??[];for(const item of list){const destruct=item.names.map(({name,alias})=>name===alias?name:`${name}: ${alias}`).join(', ');source=source.replace(item.full,`const { ${destruct} } = require(${JSON.stringify(item.target)});`);}source=source.replace(/\bexport\s+(?=(?:const|let|var|function|class)\b)/g,'');const exposed=[...(exported.get(file)??[])].map(name=>`exports.${name} = ${name};`).join('');return `modules[${JSON.stringify(file)}]=function(module,exports,require){${source}\n${exposed}};`;}
const code=`/* Generated by scripts/bundle-playtest.js. */\n(()=>{const modules=Object.create(null),cache=Object.create(null);${[...modules.keys()].map(compile).join('\n')}const require=id=>{if(cache[id])return cache[id].exports;const module={exports:{}};cache[id]=module;modules[id](module,module.exports,require);return module.exports;};try{${entryOrder.map(entry=>`require(${JSON.stringify(entry)});`).join('')} }catch(error){const host=document.querySelector('#boot-error');if(host){host.textContent=\`啟動顯示失敗：\${error?.message??String(error)}\`;host.hidden=false;}console.error(error);}})();\n`;
await mkdir(path.resolve(root,'dist'),{recursive:true});await writeFile(path.resolve(root,'dist/playtest-runtime.js'),code);
}

